@sig trait Atomic_Publication_Api {
  def id: Art.BridgeId
  def atomic_result_Id : Art.PortId
  def publication_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var publication: Mining_Threat_Retreat_Supervisor.Published_Supervisor_Result = $

  def put_publication(value : Mining_Threat_Retreat_Supervisor.Published_Supervisor_Result) : Unit = {
    Contract(
      Modifies(publication),
      Ensures(
        publication == value
      )
    )
    Spec {
      publication = value
    }

    Art.putValue(publication_Id, Mining_Threat_Retreat_Supervisor.Published_Supervisor_Result_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Atomic_Publication_Initialization_Api (
  val id: Art.BridgeId,
  val atomic_result_Id : Art.PortId,
  val publication_Id : Art.PortId) extends Atomic_Publication_Api

